import{_ as e,o as i,c as n,a6 as t}from"./chunks/framework.DycQjAfF.js";const m=JSON.parse('{"title":"Kamus Istilah","description":"Arti istilah pergudangan dan teknik yang sering dipakai di Gudang Teknik.","frontmatter":{"title":"Kamus Istilah","description":"Arti istilah pergudangan dan teknik yang sering dipakai di Gudang Teknik.","status":"ditinjau","dasar":"materi presentasi Gudang Teknik, Kumpulan Instruksi Kerja Gudang Teknik, prosedur write off QP-4.3.3, dan istilah umum pergudangan","diperbarui":"2026-10-20T00:00:00.000Z","kategori":"Gudang Teknik","sumber":["ppt-gudang-teknik","ik-gudang-teknik","qp-write-off"],"outline":2,"kata_kunci":["glosarium","istilah","kamus","definisi","singkatan"]},"headers":[],"relativePath":"divisi/glosarium.md","filePath":"divisi/glosarium.md"}'),r={name:"divisi/glosarium.md"};function s(o,a,u,l,d,h){return i(),n("div",null,[...a[0]||(a[0]=[t('<h1 id="kamus-istilah" tabindex="-1">Kamus Istilah <a class="header-anchor" href="#kamus-istilah" aria-label="Permalink to &quot;Kamus Istilah&quot;">​</a></h1><p class="lead">Istilah yang sering kamu dengar di Gudang Teknik, dijelaskan dengan bahasa sederhana. Gunakan pencarian (<kbd>Ctrl</kbd> + <kbd>K</kbd>) untuk langsung menuju istilah tertentu.</p><h2 id="umum" tabindex="-1">Umum <a class="header-anchor" href="#umum" aria-label="Permalink to &quot;Umum&quot;">​</a></h2><h3 id="gudang-teknik-warehouse" tabindex="-1">Gudang Teknik (warehouse) <a class="header-anchor" href="#gudang-teknik-warehouse" aria-label="Permalink to &quot;Gudang Teknik (warehouse)&quot;">​</a></h3><p>Tempat menerima, menyimpan, mengelola, memelihara, dan menyalurkan barang teknik untuk mendukung operasional perusahaan.</p><h3 id="user" tabindex="-1">User <a class="header-anchor" href="#user" aria-label="Permalink to &quot;User&quot;">​</a></h3><p>Orang atau bagian yang meminta dan memakai material dari gudang, misalnya teknisi perawatan.</p><h3 id="vendor-supplier" tabindex="-1">Vendor / supplier <a class="header-anchor" href="#vendor-supplier" aria-label="Permalink to &quot;Vendor / supplier&quot;">​</a></h3><p>Pihak luar yang menjual dan mengantar barang ke perusahaan.</p><h3 id="erp-wms" tabindex="-1">ERP / WMS <a class="header-anchor" href="#erp-wms" aria-label="Permalink to &quot;ERP / WMS&quot;">​</a></h3><p><em>Enterprise Resource Planning</em>, yaitu sistem komputer perusahaan yang menghubungkan data antardivisi. WMS (<em>Warehouse Management System</em>) adalah bagian sistem untuk mengelola gudang. Di Gudang Teknik, sistem ini dipakai untuk reservasi barang, mencatat barang masuk dan keluar, dan menyimpan data material.</p><h3 id="good-received" tabindex="-1">Good Received <a class="header-anchor" href="#good-received" aria-label="Permalink to &quot;Good Received&quot;">​</a></h3><p>Bagian penerimaan Gudang Teknik. Bertugas menerima, memeriksa, dan mendokumentasikan material yang datang, lalu menempatkannya di lokasi simpan.</p><h3 id="stock-keeper" tabindex="-1">Stock Keeper <a class="header-anchor" href="#stock-keeper" aria-label="Permalink to &quot;Stock Keeper&quot;">​</a></h3><p>Petugas gudang yang menyiapkan dan menyerahkan material sesuai reservasi, serta menghitung stok fisik saat stock opname.</p><h3 id="buyer-procurement-purchasing" tabindex="-1">Buyer procurement/purchasing <a class="header-anchor" href="#buyer-procurement-purchasing" aria-label="Permalink to &quot;Buyer procurement/purchasing&quot;">​</a></h3><p>Bagian pembelian yang memesan barang ke vendor. Ketidaksesuaian barang dan klaim ke vendor disampaikan lewat bagian ini.</p><h3 id="nip" tabindex="-1">NIP <a class="header-anchor" href="#nip" aria-label="Permalink to &quot;NIP&quot;">​</a></h3><p>Nomor Induk Pegawai. Saat barang diambil, NIP di reservasi dicocokkan dengan ID card karyawan yang mengambil.</p><h3 id="sttb-surat-tanda-terima-barang" tabindex="-1">STTB (Surat Tanda Terima Barang) <a class="header-anchor" href="#sttb-surat-tanda-terima-barang" aria-label="Permalink to &quot;STTB (Surat Tanda Terima Barang)&quot;">​</a></h3><p>Bukti penerimaan barang yang dulu dipakai Gudang Teknik. Sekarang <strong>sudah tidak digunakan</strong> dan digantikan oleh GRN.</p><h3 id="rak-reservasi" tabindex="-1">Rak reservasi <a class="header-anchor" href="#rak-reservasi" aria-label="Permalink to &quot;Rak reservasi&quot;">​</a></h3><p>Rak khusus tempat barang yang sudah disiapkan untuk divisi pemesan, sampai karyawan divisi itu datang mengambilnya.</p><h3 id="catatan-manual-rak" tabindex="-1">Catatan manual rak <a class="header-anchor" href="#catatan-manual-rak" aria-label="Permalink to &quot;Catatan manual rak&quot;">​</a></h3><p>Catatan tertulis yang ada di setiap rak. Diisi setiap kali barang ditaruh atau diambil dari rak tersebut. Di instruksi kerja disebut <strong>kartu stok</strong> (<em>stock card</em>).</p><h3 id="tps" tabindex="-1">TPS <a class="header-anchor" href="#tps" aria-label="Permalink to &quot;TPS&quot;">​</a></h3><p>Tempat penampungan sementara. Material yang sudah lolos pemeriksaan bisa ditaruh di sini dulu jika lokasi simpannya belum bisa dipakai. Di Blok B juga ada TPS khusus barang scrap.</p><h3 id="gudang-b3" tabindex="-1">Gudang B3 <a class="header-anchor" href="#gudang-b3" aria-label="Permalink to &quot;Gudang B3&quot;">​</a></h3><p>Gudang untuk Bahan Berbahaya dan Beracun, misalnya bahan kimia. Wajib berventilasi baik, punya exhaust fan, bak kontrol tumpahan, MSDS, eyewash station, dan APAR.</p><h3 id="apd-alat-pelindung-diri-ppe" tabindex="-1">APD (alat pelindung diri) / PPE <a class="header-anchor" href="#apd-alat-pelindung-diri-ppe" aria-label="Permalink to &quot;APD (alat pelindung diri) / PPE&quot;">​</a></h3><p>Perlengkapan untuk melindungi tubuh saat bekerja, seperti helm, sarung tangan, safety shoes, dan goggles. PPE adalah singkatan bahasa Inggrisnya (<em>personal protective equipment</em>).</p><h3 id="k3" tabindex="-1">K3 <a class="header-anchor" href="#k3" aria-label="Permalink to &quot;K3&quot;">​</a></h3><p>Keselamatan dan Kesehatan Kerja, yaitu upaya mencegah kecelakaan dan penyakit akibat kerja.</p><h2 id="inventory" tabindex="-1">Inventory <a class="header-anchor" href="#inventory" aria-label="Permalink to &quot;Inventory&quot;">​</a></h2><h3 id="inventory-persediaan" tabindex="-1">Inventory (persediaan) <a class="header-anchor" href="#inventory-persediaan" aria-label="Permalink to &quot;Inventory (persediaan)&quot;">​</a></h3><p>Seluruh material yang disimpan dan dicatat oleh gudang.</p><h3 id="stock-item" tabindex="-1">Stock item <a class="header-anchor" href="#stock-item" aria-label="Permalink to &quot;Stock item&quot;">​</a></h3><p>Material yang rutin dipakai, sehingga stoknya selalu dijaga.</p><h3 id="non-stock-item" tabindex="-1">Non-stock item <a class="header-anchor" href="#non-stock-item" aria-label="Permalink to &quot;Non-stock item&quot;">​</a></h3><p>Material yang jarang dipakai, sehingga tidak disimpan sebagai stok dan baru dibeli saat dibutuhkan.</p><h3 id="fast-moving" tabindex="-1">Fast moving <a class="header-anchor" href="#fast-moving" aria-label="Permalink to &quot;Fast moving&quot;">​</a></h3><p>Material yang diminta 2 kali atau lebih dalam sebulan.</p><h3 id="slow-moving" tabindex="-1">Slow moving <a class="header-anchor" href="#slow-moving" aria-label="Permalink to &quot;Slow moving&quot;">​</a></h3><p>Material yang diminta 1 kali dalam sebulan.</p><h3 id="cycle-counting" tabindex="-1">Cycle counting <a class="header-anchor" href="#cycle-counting" aria-label="Permalink to &quot;Cycle counting&quot;">​</a></h3><p>Metode menghitung sebagian stok secara bergiliran dan berkala, bukan menghitung seluruh gudang sekaligus. Materi Gudang Teknik juga memakai cara ini untuk menentukan fast dan slow moving.</p><h3 id="critical-stock" tabindex="-1">Critical stock <a class="header-anchor" href="#critical-stock" aria-label="Permalink to &quot;Critical stock&quot;">​</a></h3><p>Material slow moving yang harus selalu tersedia (minimal 1 unit) karena dibutuhkan mendadak, misalnya suku cadang mesin penting.</p><h3 id="write-off" tabindex="-1">Write off <a class="header-anchor" href="#write-off" aria-label="Permalink to &quot;Write off&quot;">​</a></h3><p>Penghapusbukuan, yaitu penghapusan catatan aktiva tetap dari pembukuan BPI karena barangnya tidak bisa dipakai lagi. Di gudang, istilah ini juga dipakai untuk persediaan yang sudah tidak terpakai, misalnya karena salah prediksi, mesinnya sudah tidak dipakai, atau barangnya kedaluwarsa. Lihat <a href="/WareHouse/sop/dead-stock">SOP Write Off</a>.</p><h3 id="overstock" tabindex="-1">Overstock <a class="header-anchor" href="#overstock" aria-label="Permalink to &quot;Overstock&quot;">​</a></h3><p>Stok berlebih yang tersimpan terlalu lama hingga mutunya bisa turun.</p><h3 id="stok-minimum" tabindex="-1">Stok minimum <a class="header-anchor" href="#stok-minimum" aria-label="Permalink to &quot;Stok minimum&quot;">​</a></h3><p>Batas bawah stok. Jika stok di bawah angka ini, risiko kehabisan barang tinggi.</p><h3 id="stok-maksimum" tabindex="-1">Stok maksimum <a class="header-anchor" href="#stok-maksimum" aria-label="Permalink to &quot;Stok maksimum&quot;">​</a></h3><p>Batas atas stok agar barang tidak menumpuk dan memakan tempat.</p><h3 id="rop-reorder-point" tabindex="-1">ROP (reorder point) <a class="header-anchor" href="#rop-reorder-point" aria-label="Permalink to &quot;ROP (reorder point)&quot;">​</a></h3><p>Titik pemesanan ulang. Saat stok turun sampai angka ini, material perlu dipesan kembali.</p><h3 id="safety-stock" tabindex="-1">Safety stock <a class="header-anchor" href="#safety-stock" aria-label="Permalink to &quot;Safety stock&quot;">​</a></h3><p>Stok cadangan untuk berjaga-jaga jika pemakaian melonjak atau pengiriman terlambat.</p><h3 id="lead-time" tabindex="-1">Lead time <a class="header-anchor" href="#lead-time" aria-label="Permalink to &quot;Lead time&quot;">​</a></h3><p>Waktu tunggu sejak barang dipesan sampai barang tiba di gudang.</p><h3 id="fifo-first-in-first-out" tabindex="-1">FIFO (first in, first out) <a class="header-anchor" href="#fifo-first-in-first-out" aria-label="Permalink to &quot;FIFO (first in, first out)&quot;">​</a></h3><p>Barang yang masuk lebih dulu dikeluarkan lebih dulu, agar tidak ada barang yang terlalu lama tersimpan.</p><h3 id="fefo-first-expired-first-out" tabindex="-1">FEFO (first expired, first out) <a class="header-anchor" href="#fefo-first-expired-first-out" aria-label="Permalink to &quot;FEFO (first expired, first out)&quot;">​</a></h3><p>Barang yang lebih dulu kedaluwarsa dikeluarkan lebih dulu, walaupun masuknya belakangan.</p><h3 id="reservasi" tabindex="-1">Reservasi <a class="header-anchor" href="#reservasi" aria-label="Permalink to &quot;Reservasi&quot;">​</a></h3><p>Permintaan material oleh user di ERP/WMS, berisi nomor material, jumlah, dan NIP karyawan yang akan mengambil. Reservasi disetujui Foreman atau Supervisor divisi pemesan, dan barangnya harus diambil paling lambat 3 hari.</p><h2 id="administrasi" tabindex="-1">Administrasi <a class="header-anchor" href="#administrasi" aria-label="Permalink to &quot;Administrasi&quot;">​</a></h2><h3 id="master-material" tabindex="-1">Master material <a class="header-anchor" href="#master-material" aria-label="Permalink to &quot;Master material&quot;">​</a></h3><p>Daftar induk semua material (<em>Material Master List</em>): kode, nama, spesifikasi, satuan, dan lokasi.</p><h3 id="kode-barang-nomor-material" tabindex="-1">Kode barang (nomor material) <a class="header-anchor" href="#kode-barang-nomor-material" aria-label="Permalink to &quot;Kode barang (nomor material)&quot;">​</a></h3><p>Kode unik 9 karakter sebagai identitas satu jenis material, misalnya <code>SA9A00098</code>. Terdiri dari material type, group, sub group, dan nomor urut. Lihat <a href="/WareHouse/divisi/kode-barang">Kode Barang</a>.</p><h3 id="cataloguing" tabindex="-1">Cataloguing <a class="header-anchor" href="#cataloguing" aria-label="Permalink to &quot;Cataloguing&quot;">​</a></h3><p>Penyusunan data material secara terstruktur: nomor material, deskripsi, dan satuan. Tujuannya mencegah kode ganda dan memudahkan perencanaan serta pelaporan.</p><h3 id="surat-jalan" tabindex="-1">Surat jalan <a class="header-anchor" href="#surat-jalan" aria-label="Permalink to &quot;Surat jalan&quot;">​</a></h3><p>Dokumen dari vendor yang menyertai barang saat dikirim.</p><h3 id="po-purchase-order" tabindex="-1">PO (purchase order) <a class="header-anchor" href="#po-purchase-order" aria-label="Permalink to &quot;PO (purchase order)&quot;">​</a></h3><p>Dokumen pesanan pembelian dari perusahaan ke vendor. Barang yang datang dicocokkan dengan PO.</p><h3 id="pr-purchase-request" tabindex="-1">PR (purchase request) <a class="header-anchor" href="#pr-purchase-request" aria-label="Permalink to &quot;PR (purchase request)&quot;">​</a></h3><p>Permintaan pembelian dari dalam perusahaan, yang menjadi dasar dibuatnya PO.</p><h3 id="grn-good-received-note" tabindex="-1">GRN (Good Received Note) <a class="header-anchor" href="#grn-good-received-note" aria-label="Permalink to &quot;GRN (Good Received Note)&quot;">​</a></h3><p>Laporan penerimaan material yang ditujukan kepada vendor, sekaligus bukti bahwa barang sudah diterima. Diterbitkan setelah material dinyatakan sesuai secara visual, spesifikasi, mutu, dan jumlah. GRN menggantikan STTB.</p><h3 id="material-reject" tabindex="-1">Material Reject <a class="header-anchor" href="#material-reject" aria-label="Permalink to &quot;Material Reject&quot;">​</a></h3><p>Tanda untuk material yang tidak sesuai saat diterima. Material ini dipisahkan dan diklaim ke vendor.</p><h3 id="car-corrective-action-report" tabindex="-1">CAR (Corrective Action Report) <a class="header-anchor" href="#car-corrective-action-report" aria-label="Permalink to &quot;CAR (Corrective Action Report)&quot;">​</a></h3><p>Laporan tindakan perbaikan yang diterbitkan laboratorium jika material yang diperiksanya tidak sesuai.</p><h3 id="coa-dan-mill-test-certificate" tabindex="-1">CoA dan Mill Test Certificate <a class="header-anchor" href="#coa-dan-mill-test-certificate" aria-label="Permalink to &quot;CoA dan Mill Test Certificate&quot;">​</a></h3><p>Sertifikat dari produsen yang menyatakan hasil uji mutu material. CoA adalah <em>Certificate of Analysis</em>.</p><h3 id="msds" tabindex="-1">MSDS <a class="header-anchor" href="#msds" aria-label="Permalink to &quot;MSDS&quot;">​</a></h3><p><em>Material Safety Data Sheet</em>, yaitu lembar data keselamatan bahan kimia: bahaya, cara menyimpan, dan cara menangani tumpahan.</p><h3 id="aktiva-tetap" tabindex="-1">Aktiva tetap <a class="header-anchor" href="#aktiva-tetap" aria-label="Permalink to &quot;Aktiva tetap&quot;">​</a></h3><p>Aset berwujud milik perusahaan yang dibeli atau dibangun untuk dipakai dalam operasional.</p><h3 id="capex" tabindex="-1">CAPEX <a class="header-anchor" href="#capex" aria-label="Permalink to &quot;CAPEX&quot;">​</a></h3><p><em>Capital Expenditure</em> atau pembelanjaan modal, yaitu anggaran untuk memperoleh atau meningkatkan aktiva tetap.</p><h3 id="berita-acara-kesepakatan-write-off" tabindex="-1">Berita Acara Kesepakatan Write Off <a class="header-anchor" href="#berita-acara-kesepakatan-write-off" aria-label="Permalink to &quot;Berita Acara Kesepakatan Write Off&quot;">​</a></h3><p>Dokumen kesepakatan untuk me-write off barang, dibuat oleh Chief terkait bersama Chief Logistic dan disetujui CFO serta CEO.</p><h3 id="scrap-ex-pakai" tabindex="-1">Scrap / ex pakai <a class="header-anchor" href="#scrap-ex-pakai" aria-label="Permalink to &quot;Scrap / ex pakai&quot;">​</a></h3><p>Barang bekas pakai atau sisa yang tidak dipakai lagi. Pengelolaannya mengikuti prosedur barang scrap dan penjualan scrap.</p><h3 id="spesifikasi" tabindex="-1">Spesifikasi <a class="header-anchor" href="#spesifikasi" aria-label="Permalink to &quot;Spesifikasi&quot;">​</a></h3><p>Data teknis yang membedakan satu barang dari barang lain, misalnya tipe dan ukuran.</p><h3 id="satuan" tabindex="-1">Satuan <a class="header-anchor" href="#satuan" aria-label="Permalink to &quot;Satuan&quot;">​</a></h3><p>Ukuran yang dipakai untuk menghitung barang, misalnya pcs, set, meter, kilogram, atau liter.</p><h3 id="mutasi" tabindex="-1">Mutasi <a class="header-anchor" href="#mutasi" aria-label="Permalink to &quot;Mutasi&quot;">​</a></h3><p>Perubahan stok akibat barang masuk, barang keluar, atau perpindahan lokasi.</p><h3 id="saldo" tabindex="-1">Saldo <a class="header-anchor" href="#saldo" aria-label="Permalink to &quot;Saldo&quot;">​</a></h3><p>Jumlah stok yang tercatat pada suatu waktu.</p><h3 id="stock-opname" tabindex="-1">Stock opname <a class="header-anchor" href="#stock-opname" aria-label="Permalink to &quot;Stock opname&quot;">​</a></h3><p>Kegiatan menghitung stok fisik lalu membandingkannya dengan catatan.</p><h3 id="selisih" tabindex="-1">Selisih <a class="header-anchor" href="#selisih" aria-label="Permalink to &quot;Selisih&quot;">​</a></h3><p>Perbedaan antara jumlah stok fisik dan jumlah di catatan.</p><h2 id="material-dan-teknik" tabindex="-1">Material dan teknik <a class="header-anchor" href="#material-dan-teknik" aria-label="Permalink to &quot;Material dan teknik&quot;">​</a></h2><h3 id="bearing" tabindex="-1">Bearing <a class="header-anchor" href="#bearing" aria-label="Permalink to &quot;Bearing&quot;">​</a></h3><p>Komponen yang menopang poros berputar agar gesekannya kecil. Ukurannya biasanya ditulis diameter dalam × diameter luar × tebal.</p><h3 id="seal-dan-gasket" tabindex="-1">Seal dan gasket <a class="header-anchor" href="#seal-dan-gasket" aria-label="Permalink to &quot;Seal dan gasket&quot;">​</a></h3><p>Komponen perapat untuk mencegah kebocoran. Seal umumnya untuk bagian yang bergerak, sedangkan gasket untuk sambungan yang diam.</p><h3 id="coupling" tabindex="-1">Coupling <a class="header-anchor" href="#coupling" aria-label="Permalink to &quot;Coupling&quot;">​</a></h3><p>Penghubung antara dua poros, misalnya poros motor dan poros gearbox.</p><h3 id="fastener" tabindex="-1">Fastener <a class="header-anchor" href="#fastener" aria-label="Permalink to &quot;Fastener&quot;">​</a></h3><p>Komponen pengikat, seperti baut, mur, washer, dan screw.</p><h3 id="fitting-flange-dan-valve" tabindex="-1">Fitting, flange, dan valve <a class="header-anchor" href="#fitting-flange-dan-valve" aria-label="Permalink to &quot;Fitting, flange, dan valve&quot;">​</a></h3><p>Fitting adalah sambungan pipa (elbow, tee). Flange adalah sambungan pipa berbentuk piringan yang dibaut. Valve adalah katup untuk membuka, menutup, atau mengatur aliran.</p><h3 id="consumable" tabindex="-1">Consumable <a class="header-anchor" href="#consumable" aria-label="Permalink to &quot;Consumable&quot;">​</a></h3><p>Bahan habis pakai, seperti oli, grease, amplas, dan cutting disc.</p><h3 id="instrumentasi" tabindex="-1">Instrumentasi <a class="header-anchor" href="#instrumentasi" aria-label="Permalink to &quot;Instrumentasi&quot;">​</a></h3><p>Alat ukur dan sensor, seperti pressure gauge, thermometer, dan transmitter.</p><h3 id="erw" tabindex="-1">ERW <a class="header-anchor" href="#erw" aria-label="Permalink to &quot;ERW&quot;">​</a></h3><p><em>Electric Resistance Welding</em>, yaitu proses pengelasan pipa baja menggunakan arus listrik. Lihat <a href="/WareHouse/perusahaan/">Profil Perusahaan</a>.</p><h3 id="coating" tabindex="-1">Coating <a class="header-anchor" href="#coating" aria-label="Permalink to &quot;Coating&quot;">​</a></h3><p>Lapisan pelindung pada permukaan pipa untuk mencegah korosi.</p><h2 id="indikator-kinerja-gudang" tabindex="-1">Indikator kinerja gudang <a class="header-anchor" href="#indikator-kinerja-gudang" aria-label="Permalink to &quot;Indikator kinerja gudang&quot;">​</a></h2><h3 id="order-fulfillment" tabindex="-1">Order fulfillment <a class="header-anchor" href="#order-fulfillment" aria-label="Permalink to &quot;Order fulfillment&quot;">​</a></h3><p>Seberapa tepat permintaan user dipenuhi.</p><h3 id="on-time" tabindex="-1">On-time <a class="header-anchor" href="#on-time" aria-label="Permalink to &quot;On-time&quot;">​</a></h3><p>Material tersedia tepat waktu saat dibutuhkan.</p><h3 id="space-utilization" tabindex="-1">Space utilization <a class="header-anchor" href="#space-utilization" aria-label="Permalink to &quot;Space utilization&quot;">​</a></h3><p>Seberapa efisien ruang gudang dimanfaatkan.</p><h3 id="stock-accuracy" tabindex="-1">Stock accuracy <a class="header-anchor" href="#stock-accuracy" aria-label="Permalink to &quot;Stock accuracy&quot;">​</a></h3><p>Seberapa sesuai stok fisik dengan catatan sistem.</p>',139)])])}const p=e(r,[["render",s]]);export{m as __pageData,p as default};
